mapper.insert:
INSERT INTO chat_message (session_id, user_id, role, content, created_at)
VALUES (#{sessionId}, #{userId}, #{role}, #{content},

    #{createdAt}
    NOW()

)

mapper.select:
SELECT id, session_id, user_id, role, content, created_at, feedback
FROM chat_message
WHERE session_id = #{sessionId}
ORDER BY created_at ASC
LIMIT #{limit}

SELECT id, session_id, user_id, role, content, created_at, feedback
FROM (
    SELECT id, session_id, user_id, role, content, created_at, feedback
    FROM chat_message
    WHERE session_id = #{sessionId}
    ORDER BY created_at DESC
    LIMIT #{limit}
) recent_messages
ORDER BY created_at ASC

